1| /**
2|  * wrangler-CLI harness, @goodvibes-jev/engine/platform Workers parity test.
3|  *
4|  * Spawns `wrangler dev --local` against test/workers-wrangler/worker.ts and
5|  * exercises the same endpoint surface as the Miniflare harness in
6|  * test/workers/workers.test.ts.
7|  *
8|  * IMPORTANT: `wrangler dev --local` uses Miniflare 4 as its local runtime
9|  * layer internally, it is NOT the raw workerd binary. Both this harness and
10|  * the standalone Miniflare harness share the same Miniflare 4 runtime, which
11|  * means EventSource IS available in both harnesses (Miniflare injects it).
12|  * The production EventSource absence can only be verified via a real CF
13|  * deployment. See test/workers/NOTES.md for details.
14|  *
15|  * What this harness adds over the standalone Miniflare harness:
16|  *   - Exercises wrangler's esbuild bundling pipeline (not the manual esbundle step)
17|  *   - Exercises wrangler CLI config surface (wrangler.toml, entry resolution)
18|  *   - EventSource is present in BOTH harnesses (Miniflare 4 injects it in both)
19|  *
20|  * Run:
21|  *   bun run build && bun run test:workers:wrangler
22|  *
23|  * Prerequisites:
24|  *   - wrangler must be installed (devDependency)
25|  *   - platform must be built (dist/web.js must exist)
26|  *   - No Cloudflare account or API token required (--local mode)
27|  *
28|  * Startup behaviour:
29|  *   - wrangler dev cold-starts in ~5-15s (first run populates Miniflare's workerd cache)
30|  *   - CI timeout: 120s for the job; wrangler startup timeout here: 60s
31|  *   - Port: reserved via the OS ephemeral-port allocator before wrangler starts
32|  */
33| 
34| import { resolve, dirname } from 'node:path';
35| import { fileURLToPath } from 'node:url';
36| import { spawn, execFileSync, type ChildProcess } from 'node:child_process';
37| import { createServer } from 'node:net';
38| import { describe, test, expect, beforeAll, afterAll } from 'bun:test';
39| 
40| // ---------------------------------------------------------------------------
41| // Wrangler availability check, skip all tests if wrangler is not accessible.
42| // wrangler ships as a devDependency; invoke via bunx in this project.
43| // ---------------------------------------------------------------------------
44| function checkWranglerAvailable(): boolean {
45|   try {
46|     execFileSync('bunx', ['wrangler', '--version'], { stdio: 'ignore', timeout: 10_000 });
47|     return true;
48|   } catch {
49|     return false;
50|   }
51| }
52| 
53| const wranglerAvailable = checkWranglerAvailable();
54| 
55| 
56| const __dirname = dirname(fileURLToPath(import.meta.url));
57| const HARNESS_DIR = resolve(__dirname); // test/workers-wrangler/
58| 
59| let port = 0;
60| let baseUrl = '';
61| 
62| // Maximum time to wait for wrangler to report ready (ms).
63| const STARTUP_TIMEOUT_MS = 60_000;
64| // Interval between health-check polls (ms).
65| const POLL_INTERVAL_MS = 500;
66| 
67| let wranglerProcess: ChildProcess;
68| 
69| async function findAvailablePort(): Promise<number> {
70|   const server = createServer();
71|   await new Promise<void>((resolveListen, rejectListen) => {
72|     server.once('error', rejectListen);
73|     server.listen(0, '127.0.0.1', resolveListen);
74|   });
75|   const address = server.address();
76|   await new Promise<void>((resolveClose, rejectClose) => {
77|     server.close((error) => error ? rejectClose(error) : resolveClose());
78|   });
79|   if (!address || typeof address === 'string') {
80|     throw new Error('Unable to reserve an ephemeral port for wrangler.');
81|   }
82|   return address.port;
83| }
84| 
85| // ---------------------------------------------------------------------------
86| // Lifecycle: spawn wrangler dev, poll /health, kill after tests
87| // ---------------------------------------------------------------------------
88| 
89| beforeAll(async () => {
90|   if (!wranglerAvailable) {
91|     // wrangler is not accessible via bunx, fail fast with a clear message.
92|     // Install via: npm install -g wrangler  OR ensure devDependencies are installed (bun install).
93|     throw new Error('[wrangler.test.ts] FAIL: wrangler unavailable via bunx. Run `bun install` or install wrangler globally.');
94|   }
95| 
96|   port = await findAvailablePort();
97|   baseUrl = `http://127.0.0.1:${port}`;
98|   wranglerProcess = spawn(
99|     'bunx',
100|     [
101|       'wrangler',
102|       'dev',
103|       '--local',
104|       '--port', String(port),
105|     ],
106|     {
107|       cwd: HARNESS_DIR,
108|       // Inherit stderr so wrangler startup/error output appears in test logs.
109|       stdio: ['ignore', 'pipe', 'pipe'],
110|       env: {
111|         ...process.env,
112|         // Suppress wrangler telemetry and update checks in CI.
113|         WRANGLER_SEND_METRICS: 'false',
114|         NO_COLOR: '1',
115|         // Signal non-interactive mode to wrangler (suppresses prompts).
116|         CI: 'true',
117|       },
118|     },
119|   );
120| 
121|   // Capture wrangler stderr for diagnostics on failure.
122|   const stderrLines: string[] = [];
123|   wranglerProcess.stderr?.on('data', (chunk: Buffer) => {
124|     stderrLines.push(chunk.toString());
125|   });
126|   wranglerProcess.stdout?.on('data', (chunk: Buffer) => {
127|     stderrLines.push(chunk.toString());
128|   });
129| 
130|   // Poll /health until wrangler is ready or timeout.
131|   const deadline = Date.now() + STARTUP_TIMEOUT_MS;
132|   let ready = false;
133| 
134|   while (Date.now() < deadline) {
135|     await sleep(POLL_INTERVAL_MS);
136| 
137|     // If wrangler exited early, fail immediately with diagnostics.
138|     if (wranglerProcess.exitCode !== null) {
139|       const logs = stderrLines.join('');
140|       throw new Error(
141|         `wrangler dev exited early (code ${wranglerProcess.exitCode}).\n` +
142|         `Port: ${port}\n` +
143|         `Output:\n${logs}`,
144|       );
145|     }
146| 
147|     try {
148|       const res = await fetch(`${baseUrl}/health`, { signal: AbortSignal.timeout(1000) });
149|       if (res.status === 200) {
150|         ready = true;
151|         break;
152|       }
153|     } catch {
154|       // Not ready yet, keep polling.
155|     }
156|   }
157| 
158|   if (!ready) {
159|     const logs = stderrLines.join('');
160|     wranglerProcess.kill('SIGKILL');
161|     throw new Error(
162|       `wrangler dev did not become ready within ${STARTUP_TIMEOUT_MS}ms on port ${port}.\n` +
163|       `Output:\n${logs}`,
164|     );
165|   }
166| }, STARTUP_TIMEOUT_MS + 5_000);
167| 
168| afterAll(async () => {
169|   if (wranglerProcess && wranglerProcess.exitCode === null) {
170|     wranglerProcess.kill('SIGTERM');
171|     // Give it 3s to clean up before force-killing.
172|     await sleep(3000);
173|     if (wranglerProcess.exitCode === null) {
174|       wranglerProcess.kill('SIGKILL');
175|     }
176|   }
177| });
178| 
179| function sleep(ms: number): Promise<void> {
180|   return new Promise((resolve) => {
181|     const timer = setTimeout(resolve, ms);
182|     timer.unref?.();
183|   });
184| }
185| 
186| async function get(path: string): Promise<{ status: number; body: unknown }> {
187|   const res = await fetch(`${baseUrl}${path}`, { signal: AbortSignal.timeout(10_000) });
188|   const body = await res.json();
189|   return { status: res.status, body };
190| }
191| 
192| // ---------------------------------------------------------------------------
193| // Tests, match the Miniflare harness assertions
194| // ---------------------------------------------------------------------------
195| 
196| describe('Workers wrangler: smoke', () => {
197|   test('platform loads and factory produces a valid platform object through wrangler bundling pipeline', async () => {
198|     const { status, body } = await get('/smoke');
199|     expect(status).toBe(200);
200|

201|     const b = body as Record<string, unknown>;
202|     expect(b.ok).toBe(true);
203|     expect(b.hasOperator).toBe(true);
204|     expect(b.hasAuth).toBe(true);
205|     expect(b.hasRealtime).toBe(true);
206| 
207|     const keys = b.engineKeys as string[];
208|     expect(keys).toContain('operator');
209|     expect(keys).toContain('auth');
210|     expect(keys).toContain('realtime');
211|   }, 15_000);
212| });
213| 
