215|   test('auth token is stored and retrievable inside wrangler-hosted worker', async () => {
216|     const { status, body } = await get('/auth');
217|     expect(status).toBe(200);
218| 
219|     const b = body as Record<string, unknown>;
220|     expect(b.ok).toBe(true);
221|     expect(b.tokenMatches).toBe(true);
222|     expect(b.storedToken).toBe('workers-auth-token-abc123');
223|   }, 10_000);
224| });
