227|   test('success path: mock returns real-shape JSON, result is populated', async () => {
228|     const { status, body } = await get('/transport-success');
229|     expect(status).toBe(200);
230| 
231|     const b = body as Record<string, unknown>;
232|     expect(b.ok).toBe(true);
233|     expect(b.result).not.toBeNull();
234| 
235|     const result = b.result as Record<string, unknown>;
236|     expect(result).toHaveProperty('totals');
237|     expect(result).toHaveProperty('sessions');
238|     const [session] = result.sessions as [Record<string, unknown>];
239|     expect(session.kind).toBe('tui');
240|     expect(session.lastActivityAt).toBe(1700000000000);
241|     expect(b.kind).toBeNull();
242|     expect(b.ctor).toBeNull();
