245|   test('error path: mock returns 5xx, errorKind is typed \'service\'', async () => {
246|     const { status, body } = await get('/transport-error');
247|     expect(status).toBe(200);
248| 
249|     const b = body as Record<string, unknown>;
250|     expect(b.ok).toBe(true);
251|     expect(b.result).toBeNull();
252| 
253|     const validKinds = ['auth', 'config', 'contract', 'network', 'not-found', 'protocol', 'rate-limit', 'service', 'internal', 'tool', 'validation', 'unknown'];
254|     expect(b.kind).toBe('service');
255|     expect(validKinds).toContain(b.kind as string);
256|     // esbuild mangles class names with '_' prefix; match pattern instead of exact name
257|     expect(typeof b.ctor).toBe('string');
258|     expect(b.ctor as string).toMatch(/Error$/);
259|     expect(b.kind).not.toBeNull();
260|   }, 10_000);
