1| /**
2|  * Cloudflare Workers runtime harness.
3|  *
4|  * Uses Miniflare (programmatic API, v4) to run the built ./web entry under
5|  * the actual workerd V8 isolate. Each test dispatches a real HTTP fetch to
6|  * the worker and asserts the JSON response.
7|  *
8|  * Architecture decision: ./web entry (dist/web.js) is sufficient for normal
9|  * Worker-hosted operator HTTP clients. The separate ./workers entry is only
10|  * for the optional GoodVibes Worker bridge around daemon batch queue/tick
11|  * integration.
12|  *
13|  * Module resolution: Miniflare resolves static imports relative to the
14|  * worker script location. We copy worker.ts into a tmp directory outside
15|  * dist/ to avoid racing with concurrent builds, and point modulesRoot at
16|  * packages/platform/dist/ so that `import './web.js'` resolves correctly.
17|  * The tmp directory is cleaned up in afterAll().
18|  *
19|  * Run:
20|  *   bun run build && bun test test/workers/workers.test.ts
21|  *
22|  * Or via the dedicated script:
23|  *   bun run test:workers
24|  */
25| 
26| import { resolve, dirname } from 'node:path';
27| import { readFileSync, writeFileSync, existsSync, mkdirSync, rmSync, readdirSync, copyFileSync } from 'node:fs';
28| import { fileURLToPath } from 'node:url';
29| import { describe, test, expect, beforeAll, afterAll } from 'bun:test';
30| import { Miniflare } from 'miniflare';
31| 
32| // fileURLToPath alias: __dirname here is a local const, not the Node.js global
33| // __dirname, which is unavailable in ESM.
34| const __dirname = dirname(fileURLToPath(import.meta.url));
35| const PLATFORM_DIST = resolve(__dirname, '../../platform/dist');
36| const WORKER_SOURCE = resolve(__dirname, 'worker.ts');
37| 
38| // Write to a tmp dir outside dist so concurrent builds that clean/rewrite dist
39| // cannot clobber the staged file.
40| const TMP_DIR = resolve(__dirname, '../../.test-tmp/workers-harness');
41| const WORKER_IN_TMP = resolve(TMP_DIR, '_workers-test-entry.mjs');
42| const WORKER_BUNDLED = resolve(TMP_DIR, '_workers-test-bundled.mjs');
43| 
44| let mf: Miniflare;
45| 
46| beforeAll(async () => {
47|   // Stage a full snapshot of PLATFORM_DIST in a tmp dir outside dist. modulesRoot
